package vn.edu.eaut.lab5.ui;
import vn.edu.eaut.lab5.bus.ThongKeBUS;import vn.edu.eaut.lab5.model.*;import javax.swing.*;import java.awt.*;import java.time.LocalDate;import java.time.format.DateTimeParseException;
public class ThongKePanel extends JPanel {private final ThongKeBUS bus=new ThongKeBUS();private final JTextField from=new JTextField(LocalDate.now().withDayOfMonth(1).toString()),to=new JTextField(LocalDate.now().toString());private final JButton run=new JButton("Thống kê");private final JLabel revenue=new JLabel("Doanh thu: -"),max=new JLabel("Hóa đơn cao nhất: -"),best=new JLabel("Sản phẩm bán chạy: -");
 public ThongKePanel(){setLayout(new BorderLayout(10,10));setBorder(BorderFactory.createEmptyBorder(20,20,20,20));JPanel f=new JPanel(new GridLayout(2,3,8,8));f.add(new JLabel("Ngày bắt đầu (yyyy-MM-dd):"));f.add(new JLabel("Ngày kết thúc:"));f.add(new JLabel());f.add(from);f.add(to);f.add(run);JPanel result=new JPanel(new GridLayout(3,1,8,8));result.setBorder(BorderFactory.createTitledBorder("Kết quả"));result.add(revenue);result.add(max);result.add(best);add(f,BorderLayout.NORTH);add(result,BorderLayout.CENTER);run.addActionListener(e->load());}
 private void load(){try{LocalDate a=LocalDate.parse(from.getText().trim()),b=LocalDate.parse(to.getText().trim());run.setEnabled(false);new SwingWorker<ThongKeData,Void>(){protected ThongKeData doInBackground()throws Exception{return bus.thongKe(a,b);}protected void done(){try{ThongKeData d=get();revenue.setText("Doanh thu: "+d.getDoanhThu()+" VND");HoaDon h=d.getHoaDonLonNhat();max.setText(h==null?"Hóa đơn cao nhất: Không có dữ liệu":"Hóa đơn cao nhất: #"+h.getMaHd()+" - "+h.getTongTien()+" VND ("+h.getTenKh()+")");best.setText(d.getSanPhamBanChay()==null?"Sản phẩm bán chạy: Không có dữ liệu":"Sản phẩm bán chạy: "+d.getSanPhamBanChay()+" ("+d.getSoLuongBanChay()+" sản phẩm)");}catch(Exception e){error(e);}finally{run.setEnabled(true);}}}.execute();}catch(DateTimeParseException e){error(new IllegalArgumentException("Ngày phải có dạng yyyy-MM-dd"));}}
 private void error(Exception e){Throwable x=e.getCause()==null?e:e.getCause();JOptionPane.showMessageDialog(this,x.getMessage(),"Lỗi",JOptionPane.ERROR_MESSAGE);}}
